var n=`0084-zacusca`;var a=`world-0084`;var i=`RO`;var s=`eastern-europe`;var r=4;var o=85;var l={en:`Zacuscă`,ua:`Закуска з печених овочів`};var g={en:`A classic dish from Romania, featuring eggplant, red bell pepper, yellow onion, carrot. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: баклажан, червоний солодкий перець, жовта цибуля, морква. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`eggplant`,550,`g`],[`red-bell-pepper`,450,`g`],[`yellow-onion`,160,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`carrot`,150,`g`],[`sunflower-oil`,65,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`tomato-passata`,450,`g`],[`bay-leaf`,2,`leaf`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`white-granulated-sugar`,15,`g`]]}];var u={slug:n,id:a,country:`RO`,region:s,servings:4,minutes:85,title:l,text:g,steps:d};export{i as country,u as default,a as id,o as minutes,s as region,r as servings,n as slug,d as steps,g as text,l as title};